# area: typevartuple_unpack
# hypothesis: A PEP 695 *Ts parameter captures the exact element types of a star-argument, so forward(*nums) reveals the same heterogeneous tuple, and a fixed-arity callee rejects the same starred tuple.
from typing import reveal_type


def pack[*Ts](*args: *Ts) -> tuple[*Ts]:
    return args


def forward[*Ts](*args: *Ts) -> tuple[*Ts]:
    return pack(*args)


def pair_only(a: int, b: str) -> str:
    return b * a


nums = (1, 'a', 2.5)
reveal_type(forward(*nums))
reveal_type(pack(*nums, True))
combined = (*nums, None)
reveal_type(combined)
print(forward(*nums), pack(*nums, True), combined)
print(pair_only(*(2, 'x')))
try:
    print(pair_only(*nums))  # expect-error: three positional arguments for a two-parameter callee
except TypeError as exc:
    print('runtime:', type(exc).__name__)
